import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";

export const fps = 25;
export const durationInFrames = 666;

const COLORS = {
  bg: "#1A1A2E",
  navy: "#16213E",
  blue: "#00AAFF",
  green: "#4ADE80",
  amber: "#FBBF24",
  red: "#EF4444",
  muted: "#9CA3AF",
  white: "#FFFFFF",
  card: "rgba(255,255,255,0.05)",
  cardBorder: "rgba(255,255,255,0.08)",
};

const TRANSITION = 17;
const SNAPPY = { damping: 200 };

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background_blue.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const SafeZone: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div
    style={{
      position: "absolute",
      left: 250,
      top: 250,
      width: 3340,
      height: 1660,
      overflow: "hidden",
      fontFamily: "Inter, sans-serif",
    }}
  >
    {children}
  </div>
);

const TitlePill: React.FC<{
  title: string;
  caption: string;
  delay: number;
  position: "top" | "bottom";
}> = ({ title, caption, delay, position }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: SNAPPY });
  const ty = interpolate(p, [0, 1], [position === "top" ? -30 : 30, 0]);
  return (
    <div
      style={{
        position: "absolute",
        left: "50%",
        transform: `translateX(-50%) translateY(${ty}px)`,
        opacity: p,
        top: position === "top" ? 20 : undefined,
        bottom: position === "bottom" ? 20 : undefined,
        backgroundColor: "rgba(0,170,255,0.08)",
        border: "2px solid rgba(0,170,255,0.3)",
        borderRadius: 20,
        padding: "24px 48px",
        textAlign: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      <div
        style={{
          color: COLORS.blue,
          fontWeight: 800,
          fontSize: 32,
          letterSpacing: "0.06em",
          textTransform: "uppercase",
          fontFamily: "Inter, sans-serif",
        }}
      >
        {title}
      </div>
      <div
        style={{
          color: COLORS.muted,
          fontWeight: 500,
          fontSize: 26,
          marginTop: 6,
          fontFamily: "Inter, sans-serif",
        }}
      >
        {caption}
      </div>
    </div>
  );
};

// ============ PHASE 1 ============
const PROFILE_DATA = [
  "avatar",
  "username",
  "bio",
  "followers",
  "posts[]",
];

const Phase1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const cardP = spring({ frame, fps, delay: 10, config: SNAPPY });
  const cardX = interpolate(cardP, [0, 1], [-80, 0]);

  const scannerY = interpolate(frame, [30, 90], [0, 1100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scannerOpacity = interpolate(
    frame,
    [30, 40, 80, 90],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const glowPulse =
    frame > 110 ? Math.sin(frame * 0.12) * 0.4 + 0.6 : 0;

  return (
    <AbsoluteFill>
      <Background />
      <SafeZone>
        <TitlePill
          title="INSTAGRAM PROFILE SCRAPER"
          caption="Full profile details + posts"
          delay={0}
          position="top"
        />

        {/* Left: profile card */}
        <div
          style={{
            position: "absolute",
            left: 60,
            top: 200,
            width: 1400,
            opacity: cardP,
            transform: `translateX(${cardX}px)`,
            backgroundColor: COLORS.card,
            border: `1px solid ${COLORS.cardBorder}`,
            borderRadius: 28,
            padding: 48,
            overflow: "hidden",
            fontFamily: "Inter, sans-serif",
          }}
        >
          {/* Avatar + username */}
          <div style={{ display: "flex", gap: 32, alignItems: "center" }}>
            <div
              style={{
                width: 200,
                height: 200,
                borderRadius: "50%",
                backgroundColor: "rgba(255,255,255,0.12)",
              }}
            />
            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 16 }}>
              <div style={{ width: "60%", height: 22, backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 6 }} />
              <div style={{ width: "40%", height: 16, backgroundColor: "rgba(255,255,255,0.1)", borderRadius: 5 }} />
            </div>
          </div>

          {/* Stats row */}
          <div style={{ display: "flex", justifyContent: "space-around", marginTop: 48 }}>
            {["Posts", "Followers", "Following"].map((label, i) => (
              <div key={i} style={{ textAlign: "center", fontFamily: "Inter, sans-serif" }}>
                <div
                  style={{
                    width: 120,
                    height: 28,
                    backgroundColor: "rgba(255,255,255,0.15)",
                    borderRadius: 6,
                    marginBottom: 10,
                  }}
                />
                <div style={{ color: COLORS.muted, fontSize: 28, fontWeight: 600, fontFamily: "Inter, sans-serif" }}>
                  {label}
                </div>
              </div>
            ))}
          </div>

          {/* Bio */}
          <div style={{ marginTop: 36, display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ width: "80%", height: 16, backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 5 }} />
            <div style={{ width: "65%", height: 16, backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 5 }} />
          </div>

          {/* 3x3 grid */}
          <div
            style={{
              marginTop: 36,
              display: "grid",
              gridTemplateColumns: "repeat(3, 1fr)",
              gap: 16,
            }}
          >
            {Array.from({ length: 9 }).map((_, i) => (
              <div
                key={i}
                style={{
                  aspectRatio: "1 / 1",
                  backgroundColor: "rgba(255,255,255,0.06)",
                  borderRadius: 12,
                  position: "relative",
                  background:
                    "linear-gradient(135deg, rgba(255,255,255,0.06), rgba(0,170,255,0.03))",
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    top: 10,
                    right: 10,
                    width: 18,
                    height: 18,
                    border: "2px solid rgba(255,255,255,0.4)",
                    borderRadius: i % 2 === 0 ? 3 : 9,
                  }}
                />
              </div>
            ))}
          </div>

          {/* Scanner bar */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: scannerY,
              width: "100%",
              height: 100,
              background:
                "linear-gradient(to bottom, transparent, rgba(0,170,255,0.18), transparent)",
              opacity: scannerOpacity,
              borderTop: "1.5px solid rgba(0,170,255,0.6)",
              borderBottom: "1.5px solid rgba(0,170,255,0.6)",
              pointerEvents: "none",
            }}
          />
        </div>

        {/* Right: extracted data */}
        <div
          style={{
            position: "absolute",
            right: 60,
            top: 240,
            width: 1400,
            border: "2px dashed rgba(0,170,255,0.25)",
            borderRadius: 20,
            padding: 48,
            fontFamily: "Inter, sans-serif",
          }}
        >
          <div
            style={{
              color: COLORS.muted,
              fontSize: 22,
              fontWeight: 600,
              letterSpacing: "0.15em",
              textTransform: "uppercase",
              marginBottom: 32,
              fontFamily: "Inter, sans-serif",
            }}
          >
            Extracted Data
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
            {PROFILE_DATA.map((label, i) => {
              const delay = 50 + i * 12;
              const p = spring({ frame, fps, delay, config: SNAPPY });
              const tx = interpolate(p, [0, 1], [60, 0]);
              const sc = interpolate(p, [0, 1], [0.7, 1]);
              return (
                <div
                  key={label}
                  style={{
                    backgroundColor: "rgba(0,170,255,0.12)",
                    border: "1.5px solid rgba(0,170,255,0.5)",
                    borderRadius: 12,
                    padding: "14px 28px",
                    opacity: p,
                    transform: `translateX(${tx}px) scale(${sc})`,
                    color: COLORS.blue,
                    fontFamily: "'Courier New', monospace",
                    fontSize: 28,
                    fontWeight: 600,
                    boxShadow:
                      frame > 110
                        ? `0 0 ${40 * glowPulse}px rgba(0,170,255,${0.5 * glowPulse})`
                        : "none",
                  }}
                >
                  {label}
                </div>
              );
            })}
          </div>
        </div>
      </SafeZone>
    </AbsoluteFill>
  );
};

// ============ PHASE 2 ============
const HASHTAGS = ["#travel", "#food", "#fitness", "#photography", "#design"];
const MEDIA_TILES = [
  { type: "REEL", i: 0 },
  { type: "REEL", i: 1 },
  { type: "REEL", i: 2 },
  { type: "POST", i: 3 },
  { type: "POST", i: 4 },
  { type: "POST", i: 5 },
];

const Phase2: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const highlightP = spring({ frame, fps, delay: 30, config: SNAPPY });
  const highlightScale = interpolate(highlightP, [0, 1], [1, 1.08]);
  const glowBase = interpolate(highlightP, [0, 1], [0, 40], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const glowPulse =
    frame > 150 ? Math.sin(frame * 0.1) * 0.5 + 1 : 1;
  const glow = glowBase * glowPulse;

  const connectorLength = interpolate(frame, [35, 50], [0, 280], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill>
      <Background />
      <SafeZone>
        {/* Hashtag row */}
        <div
          style={{
            position: "absolute",
            top: 100,
            left: 0,
            width: "100%",
            display: "flex",
            justifyContent: "center",
            gap: 32,
          }}
        >
          {HASHTAGS.map((tag, i) => {
            const p = spring({ frame, fps, delay: i * 12, config: SNAPPY });
            const tx = interpolate(p, [0, 1], [-30, 0]);
            const sc = interpolate(p, [0, 1], [0.7, 1]);
            const isHighlight = i === 0;
            return (
              <div
                key={tag}
                style={{
                  backgroundColor: isHighlight
                    ? "rgba(0,170,255,0.18)"
                    : "rgba(0,170,255,0.1)",
                  border: isHighlight
                    ? `2.5px solid ${COLORS.blue}`
                    : "1.5px solid rgba(0,170,255,0.25)",
                  borderRadius: 40,
                  padding: "16px 40px",
                  opacity: p,
                  transform: `translateX(${tx}px) scale(${
                    sc * (isHighlight ? highlightScale : 1)
                  })`,
                  color: isHighlight ? COLORS.white : COLORS.blue,
                  fontWeight: 700,
                  fontSize: 32,
                  fontFamily: "Inter, sans-serif",
                  boxShadow: isHighlight
                    ? `0 0 ${glow}px rgba(0,170,255,0.4)`
                    : "none",
                }}
              >
                {tag}
              </div>
            );
          })}
        </div>

        {/* Connector line from #travel */}
        <div
          style={{
            position: "absolute",
            top: 180,
            left: "50%",
            transform: `translateX(-${
              ((HASHTAGS.length - 1) / 2) * 200
            }px) translateX(-50%)`,
            width: 3,
            height: connectorLength,
            background:
              "linear-gradient(to bottom, rgba(0,170,255,0.8), rgba(0,170,255,0))",
          }}
        />

        {/* Media grid */}
        <div
          style={{
            position: "absolute",
            top: 480,
            left: "50%",
            transform: "translateX(-50%)",
            display: "grid",
            gridTemplateColumns: "repeat(3, 520px)",
            gridTemplateRows: "repeat(2, 780px)",
            gap: 32,
          }}
        >
          {MEDIA_TILES.map((tile, i) => {
            const delay = 55 + i * 12;
            const p = spring({ frame, fps, delay, config: SNAPPY });
            const ty = interpolate(p, [0, 1], [40, 0]);
            const sc = interpolate(p, [0, 1], [0.85, 1]);
            const isReel = tile.type === "REEL";
            return (
              <div
                key={i}
                style={{
                  width: 520,
                  height: 780,
                  background: isReel
                    ? "linear-gradient(135deg, #16213E, #0F1729)"
                    : "linear-gradient(135deg, rgba(0,170,255,0.15), rgba(22,33,62,0.6))",
                  border: "1.5px solid rgba(255,255,255,0.08)",
                  borderRadius: 18,
                  opacity: p,
                  transform: `translateY(${ty}px) scale(${sc})`,
                  position: "relative",
                  fontFamily: "Inter, sans-serif",
                }}
              >
                {/* Tag chip */}
                <div
                  style={{
                    position: "absolute",
                    top: 16,
                    left: 16,
                    backgroundColor: "rgba(0,0,0,0.5)",
                    padding: "6px 14px",
                    borderRadius: 8,
                    color: COLORS.white,
                    fontSize: 20,
                    fontWeight: 700,
                    fontFamily: "Inter, sans-serif",
                  }}
                >
                  {tile.type}
                </div>

                {/* Play triangle for reels */}
                {isReel && (
                  <svg
                    width="60"
                    height="60"
                    viewBox="0 0 60 60"
                    style={{
                      position: "absolute",
                      top: "50%",
                      left: "50%",
                      transform: "translate(-50%, -50%)",
                    }}
                  >
                    <polygon points="18,10 18,50 50,30" fill={COLORS.white} />
                  </svg>
                )}

                {/* Skeleton line */}
                <div
                  style={{
                    position: "absolute",
                    bottom: 24,
                    left: 24,
                    width: "60%",
                    height: 14,
                    backgroundColor: "rgba(255,255,255,0.2)",
                    borderRadius: 4,
                  }}
                />
              </div>
            );
          })}
        </div>

        <TitlePill
          title="INSTAGRAM HASHTAG SCRAPER"
          caption="Reels + posts behind any hashtag"
          delay={130}
          position="bottom"
        />
      </SafeZone>
    </AbsoluteFill>
  );
};

// ============ PHASE 3 ============
const RELATED_PINS = [
  { label: "#wanderlust", dx: -700, dy: -350 },
  { label: "#adventure", dx: 700, dy: -350 },
  { label: "#vacation", dx: -900, dy: 20 },
  { label: "#explore", dx: 900, dy: 20 },
  { label: "#travelgram", dx: 0, dy: 450 },
];

const Phase3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const centerP = spring({ frame, fps, delay: 15, config: SNAPPY });
  const centerScale = interpolate(centerP, [0, 1], [0.6, 1]);

  const centerX = 1670;
  const centerY = 830;

  return (
    <AbsoluteFill>
      <Background />
      <SafeZone>
        <TitlePill
          title="RELATED HASHTAG SCRAPER"
          caption="Go deeper · recent or top posts"
          delay={0}
          position="top"
        />

        {/* SVG connector lines */}
        <svg
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
          }}
        >
          {RELATED_PINS.map((pin, i) => {
            const delay = 35 + i * 8;
            const len = interpolate(
              frame,
              [delay, delay + 25],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            const ex = centerX + pin.dx;
            const ey = centerY + pin.dy;
            const ix = centerX + (pin.dx) * len;
            const iy = centerY + (pin.dy) * len;
            return (
              <line
                key={i}
                x1={centerX}
                y1={centerY}
                x2={ix}
                y2={iy}
                stroke="rgba(0,170,255,0.5)"
                strokeWidth={2.5}
              />
            );
          })}
        </svg>

        {/* Center #travel pill */}
        <div
          style={{
            position: "absolute",
            left: centerX,
            top: centerY,
            transform: `translate(-50%, -50%) scale(${centerScale})`,
            opacity: centerP,
            backgroundColor: "rgba(0,170,255,0.18)",
            border: `2.5px solid ${COLORS.blue}`,
            borderRadius: 40,
            padding: "24px 60px",
            color: COLORS.white,
            fontWeight: 800,
            fontSize: 56,
            fontFamily: "Inter, sans-serif",
            boxShadow: `0 0 60px rgba(0,170,255,0.5)`,
          }}
        >
          #travel
        </div>

        {/* Related pills */}
        {RELATED_PINS.map((pin, i) => {
          const delay = 60 + i * 8;
          const p = spring({ frame, fps, delay, config: SNAPPY });
          const sc = interpolate(p, [0, 1], [0.5, 1]);
          return (
            <div
              key={pin.label}
              style={{
                position: "absolute",
                left: centerX + pin.dx,
                top: centerY + pin.dy,
                transform: `translate(-50%, -50%) scale(${sc})`,
                opacity: p,
                backgroundColor: "rgba(0,170,255,0.1)",
                border: "1.5px solid rgba(0,170,255,0.25)",
                borderRadius: 40,
                padding: "16px 36px",
                color: COLORS.blue,
                fontWeight: 700,
                fontSize: 28,
                fontFamily: "Inter, sans-serif",
                whiteSpace: "nowrap",
              }}
            >
              {pin.label}
            </div>
          );
        })}

        {/* Mini post thumbs cluster (below bottom #travelgram) */}
        <div
          style={{
            position: "absolute",
            left: centerX,
            top: centerY + 600,
            transform: "translateX(-50%)",
            display: "flex",
            gap: 16,
          }}
        >
          {[0, 1, 2, 3].map((i) => {
            const delay = 95 + i * 8;
            const p = spring({ frame, fps, delay, config: SNAPPY });
            const ty = interpolate(p, [0, 1], [20, 0]);
            const isRecent = i % 2 === 0;
            return (
              <div
                key={i}
                style={{
                  width: 160,
                  height: 160,
                  borderRadius: 12,
                  background:
                    i % 2 === 0
                      ? "linear-gradient(135deg, #16213E, #0F1729)"
                      : "linear-gradient(135deg, rgba(0,170,255,0.18), rgba(22,33,62,0.6))",
                  border: "1.5px solid rgba(255,255,255,0.08)",
                  opacity: p,
                  transform: `translateY(${ty}px)`,
                  position: "relative",
                  fontFamily: "Inter, sans-serif",
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    top: 8,
                    right: 8,
                    backgroundColor: isRecent
                      ? "rgba(74,222,128,0.18)"
                      : "rgba(251,191,36,0.18)",
                    border: `1px solid ${
                      isRecent
                        ? "rgba(74,222,128,0.5)"
                        : "rgba(251,191,36,0.5)"
                    }`,
                    color: isRecent ? COLORS.green : COLORS.amber,
                    fontSize: 14,
                    fontWeight: 700,
                    padding: "4px 10px",
                    borderRadius: 6,
                    fontFamily: "Inter, sans-serif",
                  }}
                >
                  {isRecent ? "RECENT" : "★ TOP"}
                </div>
              </div>
            );
          })}
        </div>

        {/* Filter badges */}
        {(() => {
          const p = spring({ frame, fps, delay: 100, config: SNAPPY });
          const tx = interpolate(p, [0, 1], [40, 0]);
          const recentPulse = Math.sin(frame * 0.1) * 0.5 + 0.5;
          const topPulse = Math.sin(frame * 0.1 + Math.PI) * 0.5 + 0.5;
          return (
            <div
              style={{
                position: "absolute",
                right: 40,
                top: 200,
                display: "flex",
                flexDirection: "column",
                gap: 20,
                opacity: p,
                transform: `translateX(${tx}px)`,
              }}
            >
              <div
                style={{
                  backgroundColor: "rgba(74,222,128,0.12)",
                  border: `1.5px solid ${COLORS.green}`,
                  borderRadius: 16,
                  padding: "14px 32px",
                  color: COLORS.green,
                  fontWeight: 700,
                  fontSize: 26,
                  fontFamily: "Inter, sans-serif",
                  boxShadow:
                    frame > 115
                      ? `0 0 ${30 * recentPulse}px rgba(74,222,128,0.5)`
                      : "none",
                }}
              >
                Recent ↻
              </div>
              <div
                style={{
                  backgroundColor: "rgba(251,191,36,0.12)",
                  border: `1.5px solid ${COLORS.amber}`,
                  borderRadius: 16,
                  padding: "14px 32px",
                  color: COLORS.amber,
                  fontWeight: 700,
                  fontSize: 26,
                  fontFamily: "Inter, sans-serif",
                  boxShadow:
                    frame > 115
                      ? `0 0 ${30 * topPulse}px rgba(251,191,36,0.5)`
                      : "none",
                }}
              >
                ★ Top
              </div>
            </div>
          );
        })()}
      </SafeZone>
    </AbsoluteFill>
  );
};

// ============ PHASE 4 ============
const PINS = [
  { name: "Brooklyn Bridge", x: 0.25, y: 0.45, selected: false },
  { name: "Eiffel Tower", x: 0.52, y: 0.38, selected: true },
  { name: "Tokyo Tower", x: 0.78, y: 0.47, selected: false },
];

const Phase4: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const mapOpacity = interpolate(frame, [5, 25], [0, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const detailP = spring({ frame, fps, delay: 60, config: SNAPPY });
  const detailX = interpolate(detailP, [0, 1], [80, 0]);

  const selectedScale = spring({ frame, fps, delay: 55, config: SNAPPY });
  const selScale = interpolate(selectedScale, [0, 1], [1, 1.2]);

  const mapW = 2200;
  const mapH = 1400;

  return (
    <AbsoluteFill>
      <Background />
      <SafeZone>
        <TitlePill
          title="INSTAGRAM SCRAPER"
          caption="Tagged locations + post details"
          delay={0}
          position="bottom"
        />

        {/* Map container */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 120,
            width: mapW,
            height: mapH,
          }}
        >
          <Img
            src={staticFile("assets/other/world.svg")}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "contain",
              filter:
                "invert(1) sepia(1) saturate(2) hue-rotate(180deg)",
              opacity: mapOpacity,
            }}
          />
          {/* Radial glow */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(closest-side, rgba(0,170,255,0.06), transparent)",
              pointerEvents: "none",
            }}
          />

          {/* Pins */}
          {PINS.map((pin, i) => {
            const delay = 25 + i * 12;
            const p = spring({ frame, fps, delay, config: SNAPPY });
            const ty = interpolate(p, [0, 1], [-30, 0]);
            const sc = interpolate(p, [0, 1], [0, 1]);
            const finalScale = pin.selected ? sc * selScale : sc;
            const px = pin.x * mapW;
            const py = pin.y * mapH;

            const labelP = spring({ frame, fps, delay: 90 + i * 5, config: SNAPPY });
            const labelTy = interpolate(labelP, [0, 1], [10, 0]);

            const selGlow = pin.selected
              ? 60 + Math.sin(frame * 0.1) * 0.3 * 20
              : 36;

            return (
              <div key={i}>
                {/* Pin label */}
                <div
                  style={{
                    position: "absolute",
                    left: px,
                    top: py - 90,
                    transform: `translateX(-50%) translateY(${labelTy}px)`,
                    opacity: labelP,
                    backgroundColor: "rgba(22,33,62,0.9)",
                    border: pin.selected
                      ? `2px solid ${COLORS.blue}`
                      : "1.5px solid rgba(0,170,255,0.3)",
                    borderRadius: 12,
                    padding: "10px 20px",
                    color: COLORS.white,
                    fontSize: 24,
                    fontWeight: 700,
                    fontFamily: "Inter, sans-serif",
                    whiteSpace: "nowrap",
                  }}
                >
                  {pin.name}
                </div>

                {/* Pin stem */}
                <div
                  style={{
                    position: "absolute",
                    left: px - 2,
                    top: py + 24,
                    width: 4,
                    height: 32,
                    backgroundColor: COLORS.blue,
                    opacity: p,
                    transformOrigin: "top",
                    transform: `scaleY(${finalScale})`,
                  }}
                />

                {/* Pin dot */}
                <div
                  style={{
                    position: "absolute",
                    left: px,
                    top: py,
                    transform: `translate(-50%, -50%) translateY(${ty}px) scale(${finalScale})`,
                    opacity: p,
                    width: 48,
                    height: 48,
                    borderRadius: "50%",
                    backgroundColor: COLORS.blue,
                    border: "5px solid rgba(0,170,255,0.4)",
                    boxShadow: `0 0 ${selGlow}px rgba(0,170,255,0.7)`,
                  }}
                />
              </div>
            );
          })}
        </div>

        {/* Detail card right */}
        <div
          style={{
            position: "absolute",
            right: 40,
            top: 220,
            width: 1100,
            backgroundColor: COLORS.card,
            border: `1px solid ${COLORS.cardBorder}`,
            borderRadius: 28,
            padding: 44,
            opacity: detailP,
            transform: `translateX(${detailX}px)`,
            fontFamily: "Inter, sans-serif",
          }}
        >
          <div
            style={{
              color: COLORS.blue,
              fontWeight: 800,
              fontSize: 36,
              letterSpacing: "0.04em",
              fontFamily: "Inter, sans-serif",
            }}
          >
            Eiffel Tower, Paris
          </div>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              marginTop: 14,
              color: COLORS.muted,
              fontSize: 26,
              fontWeight: 600,
              fontFamily: "Inter, sans-serif",
            }}
          >
            <svg width="24" height="24" viewBox="0 0 24 24">
              <path
                d="M12 2 C8 2 5 5 5 9 C5 14 12 22 12 22 C12 22 19 14 19 9 C19 5 16 2 12 2 Z"
                fill="none"
                stroke={COLORS.blue}
                strokeWidth="2.5"
                strokeLinejoin="round"
              />
              <circle cx="12" cy="9" r="2.5" fill={COLORS.blue} />
            </svg>
            Tagged posts · 12,847
          </div>

          {/* 2x2 grid */}
          <div
            style={{
              marginTop: 32,
              display: "grid",
              gridTemplateColumns: "repeat(2, 200px)",
              gap: 16,
            }}
          >
            {[0, 1, 2, 3].map((i) => {
              const delay = 80 + i * 8;
              const p = spring({ frame, fps, delay, config: SNAPPY });
              return (
                <div
                  key={i}
                  style={{
                    width: 200,
                    height: 200,
                    background:
                      "linear-gradient(135deg, #16213E, #0F1729)",
                    border: "1.5px solid rgba(255,255,255,0.08)",
                    borderRadius: 14,
                    opacity: p,
                    position: "relative",
                    fontFamily: "Inter, sans-serif",
                  }}
                >
                  <svg
                    width="20"
                    height="20"
                    viewBox="0 0 24 24"
                    style={{
                      position: "absolute",
                      bottom: 10,
                      right: 10,
                      opacity: 0.7,
                    }}
                  >
                    <path
                      d="M12 2 C8 2 5 5 5 9 C5 14 12 22 12 22 C12 22 19 14 19 9 C19 5 16 2 12 2 Z"
                      fill="none"
                      stroke={COLORS.white}
                      strokeWidth="2.5"
                      strokeLinejoin="round"
                    />
                    <circle cx="12" cy="9" r="2.5" fill={COLORS.white} />
                  </svg>
                </div>
              );
            })}
          </div>

          {/* Skeleton metadata */}
          <div style={{ marginTop: 32, display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ width: "75%", height: 14, backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 4 }} />
            <div style={{ width: "55%", height: 14, backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 4 }} />
          </div>
        </div>
      </SafeZone>
    </AbsoluteFill>
  );
};

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: "#000000" }} />
);

const MainComposition: React.FC = () => (
  <TransitionSeries>
    <TransitionSeries.Sequence durationInFrames={175 + TRANSITION}>
      <Phase1 />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={182 + TRANSITION}>
      <Phase2 />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={153 + TRANSITION}>
      <Phase3 />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={136 + TRANSITION}>
      <Phase4 />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={20}>
      <BlackScreen />
    </TransitionSeries.Sequence>
  </TransitionSeries>
);

export default MainComposition;
